    document.getElementById('modal-image').innerHTML = `<div style="width:100%;padding:4rem 0;text-align:center;background:linear-gradient(135deg, var(--bg-card), var(--modal-bg));border-radius:0.75rem;color:var(--text-subtle);font-size:0.875rem;">📄 ${t.modal.cvPlaceholder}</div>`;
